import json
from typing import List

class Claim:
    def __init__(self, claim: str, supported_by: str, status: str):
        self.claim = claim
        self.supported_by = supported_by
        self.status = status

    def __str__(self):
        return f"Claim: {self.claim}, Supported by: {self.supported_by}, Status: {self.status}"


def decompose_candiate_answer(candiate_answer: str, evidence: str) -> List[Claim]:
    claims = []
    for claim in candiate_answer.split(","):
        claim = claim.strip()
        if claim.startswith("QUESTION"):
            continue
        claim = claim[9:]
        status = "missing"
        if claim in evidence:
            status = "supported"
        else:
            status = "contradicted"
        claims.append(Claim(claim, "", status))
    return claims

